const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // A point within Siskiyou County, CA, near known fire activity in Aug 2021.
    const fireOriginPoint = ee.Geometry.Point([-122.63, 41.55]);

    // An area of interest 20 miles (approx 32,200 meters) north of the fire origin.
    // This uses a projection to accurately calculate the distance and create the point.
    const northPoint = fireOriginPoint.transform('EPSG:32610', 1).buffer(32200).bounds().centroid('EPSG:4326', 1);

    // Define circular regions of interest (5km radius) to sample pixel values.
    const fireRoi = fireOriginPoint.buffer(5000);
    const northRoi = northPoint.buffer(5000);

    // Date of interest. A 3-day window is used to increase the chance of a clear image.
    const startDate = '2021-08-18';
    const endDate = '2021-08-20';

    // 2. Data Acquisition & Check
    // Use Sentinel-2 Level-1C (Top of Atmosphere) as it shows atmospheric effects like smoke clearly.
    let imageCollection = ee.ImageCollection('COPERNICUS/S2')
        .filterBounds(fireOriginPoint.buffer(40000)) // A large buffer to ensure both ROIs are covered
        .filterDate(startDate, endDate)
        .sort('CLOUDY_PIXEL_PERCENTAGE', true); // Get the clearest image first

    const collectionSize = imageCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log("No Sentinel-2 images found for the specified date and location.");
        console.log("A"); // Likely fire/smoke was visible on a nearby day, but not in this window. For the purpose of the query, we can't confirm.
        return;
    }

    // Select the first (least cloudy) image.
    const image = ee.Image(imageCollection.first());

    // 3. Processing & Calculation
    // We will use the red band (B4) as a proxy for smoke density. Smoke appears bright white/grey.
    // A simple mean of the red band brightness will be calculated for both areas.
    // Higher values suggest the presence of bright smoke or clouds.
    const reducer = ee.Reducer.mean();
    const scale = 1000; // Use a coarse scale to avoid timeouts.

    const fireRegionStats = image.select('B4').reduceRegion({
        reducer: reducer,
        geometry: fireRoi,
        scale: scale,
        maxPixels: 1e9
    });

    const northRegionStats = image.select('B4').reduceRegion({
        reducer: reducer,
        geometry: northRoi,
        scale: scale,
        maxPixels: 1e9
    });

    // Extract the values. Use ee.Number for safe server-side casting and operations.
    const fireBrightness = ee.Number(fireRegionStats.get('B4'));
    const northBrightness = ee.Number(northRegionStats.get('B4'));

    const fireBrightnessInfo = fireBrightness.getInfo();
    const northBrightnessInfo = northBrightness.getInfo();
    const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();

    // 4. Validation
    if (fireBrightnessInfo === null || northBrightnessInfo === null) {
        console.log("Calculation failed: Could not retrieve brightness values from one or both regions.");
        console.log("C3");
        return;
    }

    const fireRoiPixels = image.select('B4').reduceRegion({reducer: ee.Reducer.count(), geometry: fireRoi, scale: scale}).get('B4').getInfo();
    const northRoiPixels = image.select('B4').reduceRegion({reducer: ee.Reducer.count(), geometry: northRoi, scale: scale}).get('B4').getInfo();

    if (fireRoiPixels === 0 || northRoiPixels === 0) {
        console.log("No valid pixels found in one or both ROIs.");
        console.log("C2");
        return;
    }

    // Logic: Smoke plumes are significantly brighter than the typical ground surface (vegetation, soil).
    // If the northern point is also very bright, and its brightness is at least 75% of the source brightness,
    // it suggests the plume extended that far. A threshold of 2500 for TOA reflectance is used for "bright".
    const isSmokeAtSource = fireBrightnessInfo > 2500;
    const isSmokeAtNorth = northBrightnessInfo > 2500;
    const isPlumeConnected = northBrightnessInfo > (fireBrightnessInfo * 0.75);

    // 5. Final Answer
    console.log(`Image found on: ${imageDate}`);
    console.log(`Source area pixel count: ${fireRoiPixels}`);
    console.log(`North area pixel count: ${northRoiPixels}`);
    console.log(`Source area mean brightness (B4): ${Math.round(fireBrightnessInfo)}`);
    console.log(`North area (20 miles) mean brightness (B4): ${Math.round(northBrightnessInfo)}`);

    if (isSmokeAtSource && isSmokeAtNorth && isPlumeConnected) {
        console.log("Evidence: High brightness found at both the source and 20 miles north.");
        console.log("A");
    } else {
        console.log("Evidence: Brightness at 20 miles north is not indicative of a dense smoke plume from the source.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during Earth Engine initialization or analysis.");
        console.error(e);
        console.log("D");
    }
}

initEE();
